parameters.jsCode:
const r = $input.first().json;
const chatId = String($('Normalize Params').item.json.chat_id);
if (r.budget == null) {
  return [{ json: { chat_id: chatId, reply: 'Пока не задан лимит. Отправь команду /start, чтобы установить его.' } }];
}
const budget = Number(r.budget);
const spent = Number(r.spent);
const percent = budget > 0 ? Math.round((spent / budget) * 100) : 0;
return [{ json: { chat_id: chatId, reply: `\u0422ы потратил ${spent} \u0440. из ${budget} \u0440. (${percent}%)` } }];

const rows = $input.all().map(i => i.json).filter(r => r.category != null);
const chatId = String($('Normalize Params').item.json.chat_id);
if (!rows.length) {
  return [{ json: { chat_id: chatId, report: '\ud83d\udced \u0412 \u044d\u0442\u043e\u043c \u043c\u0435\u0441\u044f\u0446\u0435 \u0442\u0440\u0430\u0442 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442.' } }];
}
const total = rows.reduce((s, r) => s + Number(r.total), 0);
const lines = rows.map(r => `\u2022 ${r.category}: ${Number(r.total)} \u0440. (${total ? Math.round(Number(r.total) / total * 100) : 0}%)`);
return [{ json: { chat_id: chatId, report: `\ud83e\uddfe \u041e\u0442\u0447\u0435\u0442 \u043f\u043e \u0442\u0440\u0430\u0442\u0430\u043c \u0437\u0430 \u043c\u0435\u0441\u044f\u0446\n\n\u0412\u0441\u0435\u0433\u043e: ${total} \u0440.\n\n${lines.join('\n')}` } }];

