parameters.jsCode:
const r = $input.first().json;
const chatId = String($('Normalize Params').item.json.chat_id);
const exp = $('AI Parse Expense').item.json.output;
let msg = `\u2705 \u0417\u0430\u043f\u0438\u0441\u0430\u043b: ${exp.category} \u2014 ${Number(exp.sum)} \u0440.`;
if (r.budget != null) {
  const budget = Number(r.budget);
  const spent = Number(r.spent);
  const percent = budget > 0 ? Math.round(spent / budget * 100) : 0;
  msg += `\n\u0412\u0441\u0435\u0433\u043e \u0437\u0430 \u043c\u0435\u0441\u044f\u0446: ${spent} \u0440. \u0438\u0437 ${budget} \u0440. (${percent}%)`;
}
return [{ json: { chat_id: chatId, reply: msg } }];

const yesterday = new Date(Date.now() - 24 * 3600 * 1000).toLocaleDateString('ru-RU', { timeZone: 'Europe/Moscow' });
return $input.all().map(i => {
  const r = i.json;
  const cats = (r.by_category || []).map(c => `\u2022 ${c.category}: ${Number(c.total)} \u0440.`).join('\n');
  return {
    json: {
      chat_id: String(r.chat_id),
      report: `\ud83c\udf19 \u041e\u0442\u0447\u0451\u0442 \u0437\u0430 \u0432\u0447\u0435\u0440\u0430 (${yesterday})\n\n\u0412\u0441\u0435\u0433\u043e: ${Number(r.total)} \u0440.\n${cats}`
    }
  };
});

parameters.query:
CREATE TABLE IF NOT EXISTS bot_users (
  user_id     BIGINT PRIMARY KEY,
  chat_id     BIGINT NOT NULL,
  budget      NUMERIC NOT NULL,
  updated_at  TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS bot_spendings (
  id         BIGSERIAL PRIMARY KEY,
  user_id    BIGINT NOT NULL,
  category   TEXT NOT NULL,
  sum        NUMERIC NOT NULL,
  spent_at   DATE NOT NULL DEFAULT ((now() at time zone 'Europe/Moscow')::date),
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_spendings_user_date ON bot_spendings (user_id, spent_at);
